//! `hot-text-layout`: link grit-lib's hot code path contiguously into every dependent binary.
//!
//! The kernel maps file-backed code in 64 KiB fault-around windows, and the few thousand
//! library functions common operations run are otherwise scattered over the whole `.text`
//! of a binary, so a short command makes several MiB of code resident. `hot-text.ld`
//! (generated by `scripts/gen_hot_text_layout.py`) lists those functions; LLD places them in
//! one `.text.grit_hot` output section ahead of `.text` (`INSERT BEFORE .text`), leaving the
//! rest of the default layout alone.
//!
//! A library cannot pass linker arguments to its dependents, but its native libraries reach
//! every final link. So the fragment is published as `libgrit_lib_hot_text.so` and linked
//! with `-l`: LLD reads a text input file as an implicit linker script. GNU ld rejects
//! `SECTIONS` there, so the feature only acts on `x86_64-unknown-linux-gnu`, where rustc
//! links with LLD by default. Set `GRIT_HOT_TEXT_LAYOUT=0` to turn it off, e.g. when linking
//! with another linker.

use std::env;
use std::fs;
use std::path::PathBuf;

include!("hot_text_linker_support.rs");

fn main() {
    println!("cargo:rerun-if-changed=hot-text.ld");
    println!("cargo:rerun-if-changed=hot_text_linker_support.rs");
    println!("cargo:rerun-if-env-changed=GRIT_HOT_TEXT_LAYOUT");
    println!("cargo:rerun-if-env-changed=RUSTFLAGS");
    println!("cargo:rerun-if-env-changed=CARGO_ENCODED_RUSTFLAGS");
    if env::var_os("CARGO_FEATURE_HOT_TEXT_LAYOUT").is_none()
        || env::var("GRIT_HOT_TEXT_LAYOUT").as_deref() == Ok("0")
        || env::var("TARGET").as_deref() != Ok("x86_64-unknown-linux-gnu")
        || !linker_supports_hot_text_layout()
    {
        return;
    }
    let (Some(manifest_dir), Some(out_dir)) =
        (env::var_os("CARGO_MANIFEST_DIR"), env::var_os("OUT_DIR"))
    else {
        return;
    };
    let out_dir = PathBuf::from(out_dir);
    let script = PathBuf::from(manifest_dir).join("hot-text.ld");
    if let Err(err) = fs::copy(&script, out_dir.join("libgrit_lib_hot_text.so")) {
        println!(
            "cargo:warning=hot-text-layout: cannot copy {}: {err}",
            script.display()
        );
        return;
    }
    println!("cargo:rustc-link-search=native={}", out_dir.display());
    println!("cargo:rustc-link-lib=dylib=grit_lib_hot_text");
}
